// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Void"

A grid of blocks is used to give the impression of an abandoned city.
An iteration on a shader I created last year almost at the same time.
I improved the render quality and legibility of the scene.
For example, I added the road and the median strip and played with the
contrast of the buildings' grays and the yellow of the median strip.
The camera perspective and movement have been altered to give a better
sense of scale.

In the original shader I said, "Look how easily we can be fooled.
These are just a few boxes. A little darkness and noise and we think
we're in a deserted city. At least I do."

Well, let me know what you think.
*/

let theShader, mouseZ = 0;

function mousePressed() {
	mouseZ = 1;
}

function mouseReleased() {
	mouseZ = 0;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2476775/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  theShader.setUniform("touch", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
  theShader.setUniform("pointerCount", mouseZ);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Enable WebGL2
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; in vec2 aTexCoord; out vec2 vTexCoord;
void main() { vTexCoord = aTexCoord; vec4 positionVec4 = vec4(aPosition, 1.0);  
positionVec4.xy = positionVec4.xy * 2.0 - 1.0; gl_Position = positionVec4; }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Iteration on my shader Dystopia (11/13/2023)
* https://codepen.io/atzedent/details/abXwMRL
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
uniform vec2 touch;
uniform int pointerCount;
#define FC gl_FragCoord.xy
#define R resolution
#define P pointerCount
#define mouse (touch/R)
#define T mod(time+40.,180.)
// Easy timer switch for camera and texture
#define TICK (fract(T*.025))
#define MN min(R.x,R.y)
#define N normalize
#define hue(a) (.5+.5*sin(3.3*a*vec3(0,1,2)))
#define lum(a) vec3(dot(a,vec3(.21,.71,.07)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define box(p,s,r) length(max(abs(p)-(s),.0))+min(.0,max(max(abs((p).x)-(s).x,abs((p).y)-(s).y),abs((p).z)-(s).z))-r
// Following three lines define a random number generator
#define Q(p) fract(p*vec2(12.9898,12.233))
#define Y(p) (p+dot(Q(p),Q(p)+34.56))
#define rnd(p) fract(Y(p).x*Y(p).y)
// Definition of the rendered scene objects
vec4 map(vec3 p) {
	vec3 q=p, st=p;
	const float n=3.;
	p.xz=(fract(p.xz/n)-.5)*n;
	vec2 id=(floor(q.xz/n)-.5)*n;
	float h=max(.2,rnd(id)*2.5),
	w=max(.5,1.-rnd(id));
	q=mod(q*10.,1.125);
	float bld=box((p-vec3(0,h,0))+.05,vec3(w,h,w),.0125),
	wnd=box(q,vec3(1),.005);
	// decide on the timer if the building is to be a scaffold
	bld=max(bld,-(TICK<.5?max(wnd,-(bld+.05)):min(wnd,bld-.025)));
	// a is the buildings, b the street
	vec4 a=vec4(bld,1,id), b=vec4(st.y+.66,0,vec2(0));
	return a.x<b.x ? a : b;
}
// Camera movement reacts to the timer switch TICK and the mouse
void cam(inout vec3 p) {
	if (P>0) {
		p.yz*=rot(-mouse.y*3.1415+1.5707);
		p.xz*=rot(3.1415-mouse.x*6.2832);
	} else {
		if (TICK>.5) {
			p.yz*=rot(-.45);
			p.xz*=rot(2.7+sin(T*.05));
		} else {
			p.yz*=rot((sin(T*.1)*.5-.5)*.95);
			p.xz*=rot(3.1415+cos(T*.1)*.5);
		}
	}
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0),
	rd=N(vec3(uv,.8));
	cam(p); cam(rd);
	p.z+=T*3.;
	const float steps=60., maxd=30.;
	float i=.0,dd=.0,mat=-1.,diffuse=mix(.3,.5,rnd(uv*10.+vec2(T,1)));
	vec2 id=vec2(0);
	// the raymarching loop
	for (; i<steps; i++) {
		vec4 d=map(p);
		// add white noise to reduce artifacts and add texture
		d.x*=diffuse;
		if (d.x<1e-2) {
			mat=d.y;
			id=d.zw;
			break;
		}
		if (d.x>maxd) break;
		p+=rd*d.x;
		dd+=d.x;
	}
	if (dd<maxd) {
		if (mat==1.) {
			col+=(steps-i)/steps;
			// colorize the buildings individually and reduce to grayscale afterwards
			col*=TICK<.5?1.618*lum(max(hue(id.x+id.y+rnd(id)),.4)):vec3(1.2);
		} else if (mat==.0) {
			// add the median strip to the street
			col+=vec3(1,.7,.025)*step(max(abs(p.x*12.+10.)-.05,mod(p.z,2.)),1.);
			// brighten the street just a bit
			col+=.12;
		}
	}
	col=max(col,.08);
	O=vec4(col,1);
}

